export interface PinnedRoot {
    /** SubjectPublicKeyInfo DER. The root certificate's other fields, validity included, are ignored. */
    spki: Buffer
    /** Whether factory-provisioned chains may end here; they predate RKP and use the RSA root only. */
    factory: boolean
}

// From https://android.googleapis.com/attestation/root. One RSA-4096 key backs the 2016, 2019
// and 2022 root certificates.
const GOOGLE_RSA_ROOT_SPKI =
    ""

// The P-384 "Key Attestation CA1" root, which RKP chains move to from 2026.
const GOOGLE_P384_ROOT_SPKI =
    "MHYwEAYHKoZIzj0CAQYFK4EEACIDYgAEI9ojcU7fPlsFCjxy6IRqzgeOoK0b+YsV9FPQywiyw8EQRTkJ9u3qwfnI4DGoSLlBqClTXJfgfCcZvs60FikNMHnu4fkRzObfgDkU2KNXezT9/RQ+XvNslxPHrHCowhGr"

/** A new Google root needs an issuer release. */
export const GOOGLE_ATTESTATION_ROOTS: readonly PinnedRoot[] = [
    { spki: Buffer.from(GOOGLE_RSA_ROOT_SPKI, "base64"), factory: true },
    { spki: Buffer.from(GOOGLE_P384_ROOT_SPKI, "base64"), factory: false }
]
